import{c as t,Q as o,j as n,m as r}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"Less Context, Better Agents: Efficient Context Engineering for Long-Horizon Tool-Using LLM Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.10209","title":"Less Context, Better Agents: Efficient Context Engineering for Long-Horizon Tool-Using LLM Agents","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.10209,"authors":["Abhilasha Lodha","Mahsa Pahlavikhah Varnosfaderani","Abir Chakraborty","Abhinav Mithal"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2606.10209v1","pdf_path":"pdfs/2606.10209.pdf","published_date":"2026-06-08T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-08-less-context-better-agents-2606-10209.md","filePath":"research/papers/2026-06-08-less-context-better-agents-2606-10209.md","lastUpdated":1785909234000}'),a={name:"research/papers/2026-06-08-less-context-better-agents-2606-10209.md"};function s(i,e,l,c,h,g){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="less-context-better-agents-efficient-context-engineering-for-long-horizon-tool-using-llm-agents" tabindex="-1">Less Context, Better Agents: Efficient Context Engineering for Long-Horizon Tool-Using LLM Agents <a class="header-anchor" href="#less-context-better-agents-efficient-context-engineering-for-long-horizon-tool-using-llm-agents" aria-label="Permalink to &quot;Less Context, Better Agents: Efficient Context Engineering for Long-Horizon Tool-Using LLM Agents&quot;">​</a></h1><p><strong>Authors</strong>: Abhilasha Lodha, Mahsa Pahlavikhah Varnosfaderani, Abir Chakraborty, Abhinav Mithal <strong>Published</strong>: June 08, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.10209" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.10209</a> · <a href="https://arxiv.org/html/2606.10209v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.10209 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.10209" target="_blank" rel="noreferrer">research/papers/pdfs/2606.10209.pdf</a> (17 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Large language models deployed as autonomous agents for enterprise workflows face a key challenge: verbose tool responses from enterprise systems can cause context overflow, stale-state errors, and high inference cost. We study this problem in automated expense itemization in Microsoft Dynamics 365 Finance and Operations using Model Context Protocol tools. We evaluate four GPT-5 configurations on a 50-task hotel expense benchmark: no user model, full conversation history, context pruned to the last 5 tool call/response pairs, and pruning with automated summarization. Results are averaged across 5 independent runs, with the user model held constant for the context-engineering comparison. The no-user-model baseline achieves only 8.0% complete itemization. Full-context retention improves completion to 71.0%, but consumes 1,480,996 tokens and 14.56 hours per benchmark. Pruning to the last 5 tool calls improves completion to 79.0% while reducing token use to 535,274 and runtime to 5.39 hours. Adding summarization achieves the best result: 91.6% complete itemization and 99.64% average amount itemized, with 553,374 tokens and 5.79 hours. We further report confidence intervals, effect-size analysis, sensitivity over pruning and summary windows, failure analysis, results across five expense types grouped into three categories, and cross-model evidence with Claude Sonnet 4.5. These results show that, for this class of enterprise tool-use workflow, selective retention of recent tool interactions plus compact summarization can improve both reliability and efficiency compared with full-history retention.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>在真實 enterprise ERP（Microsoft Dynamics 365）上以 MCP tools 做 long-horizon agentic 任務，建立 50-task hotel expense benchmark</li><li>系統評估四種 context 策略：no user model / full history / pruning-only（last 5 tool pairs）/ pruning + summarization</li><li>量化證明 context overflow 是 LLM agent 可靠性與成本的核心瓶頸，不是 model 能力問題</li><li>提供跨模型驗證（Claude Sonnet 4.5），增強結論泛化性</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li><strong>無 user model</strong>：8.0% 完成率（baseline）</li><li><strong>Full history</strong>：71.0% 完成率，耗 1,480,996 tokens，14.56 小時/benchmark</li><li><strong>Pruning（last 5 pairs）</strong>：79.0% 完成率，535,274 tokens，5.39 小時（↓64% tokens，↓63% 時間）</li><li><strong>Pruning + summarization</strong>：91.6% 完成率，99.64% 金額正確率，553,374 tokens，5.79 小時 — <strong>最佳</strong></li><li>Summarization 比 full history 多用 ~3% tokens 但完成率提升 20.6pp</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>領域特定：benchmark 限於 hotel expense itemization，泛化到其他 enterprise workflow 需另行驗證</li><li>小規模 benchmark（50 tasks），統計置信區間較寬</li><li>Pruning window 固定為 last 5 pairs，動態調整策略未探索</li><li>User model 作為固定常數控制，實際部署中 user model 本身亦可能需要 context 管理</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>NLAH 原則直接對應</strong>：論文的 pruning + summarization 策略實驗性地佐證了 <code>context-management.md</code> 的 NLAH 原則（Right context &gt; more context）——保留最近 tool 互動而非全部 history，在 reliability 與 token 效率上同時勝出</li><li><strong>context-management token budget</strong>：論文的 token 數字（full history 1.48M vs pruning 0.55M）量化了 token overflow 的真實代價，與 workspace token budget 軟性上限的設計動機吻合；<code>context-management.md</code> 的 compact hint 機制在概念上與論文的 summarization window 同源</li><li><strong>unverified_success 閘門</strong>：論文指出 agent 在 full-history 條件下會產生 stale-state errors（以為任務已完成實則未完成），這與 <code>core.md</code> TEST 階段的 <code>unverified_success</code> 閘門所防範的失敗模式一致——LLM 自報「成功」不等於真正完成</li><li>⚠️ <strong>落地門檻</strong>：論文場景為單一確定性 ERP 任務（expense itemization），workspace 的 subagent fan-out 涉及多層協作與非確定性任務；pruning window 大小需按具體 tool response verbosity 校準，不可直接套用 last-5 數字</li></ul>',16)])])}const m=t(a,[["render",s]]);export{d as __pageData,m as default};
